def max_string_value(N, M, S, T):
    result = list(S)

    for k in range(1, M + 1):
        i = int(T[k - 1])
        if i <= N:
            result[i - 1] = str(k)

    return ''.join(result)

# Example usage
N, M = map(int, input().split())
S = input()
T = input()

print(max_string_value(N, M, S, T))
